provider = #{provider}, base_url = #{baseUrl}, api_key = #{apiKey}, model_name = #{modelName}, config_name = #{configName}, sort = #{sort}, temperature = #{temperature}, is_active = CASE WHEN #{isActive} IS TRUE THEN 1 ELSE 0 END, max_tokens = #{maxTokens}, model_type = #{modelType}, completions_path = #{completionsPath}, embeddings_path = #{embeddingsPath}, is_deleted = #{isDeleted}, proxy_enabled = CASE WHEN #{proxyEnabled} IS TRUE THEN 1 ELSE 0 END, proxy_host = #{proxyHost}, proxy_port = #{proxyPort}, proxy_username = #{proxyUsername}, proxy_password = #{proxyPassword}, updated_time = #{updatedTime}
WHERE id = #{id}

